describe('Phone Number Field Validation', () => {
  beforeEach(() => {
    cy.visit('/contact');
  });

  it('should accept only numeric input in phone number field', () => {
    // Intercept the API call to validate phone number
    cy.intercept('POST', '/api/validate-phone').as('validatePhone');

    // Get the phone number input field
    cy.get('[data-testid="phone-input"]').should('be.visible');

    // Type a valid numeric phone number
    cy.get('[data-testid="phone-input"]').type('1234567890');

    // Verify the input value is correct
    cy.get('[data-testid="phone-input"]').should('have.value', '1234567890');

    // Click the submit button
    cy.get('[data-testid="submit-btn"]').click();

    // Wait for the API validation response
    cy.wait('@validatePhone').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Phone number validated successfully');
  });

  it('should reject non-numeric input in phone number field', () => {
    // Intercept the API call to validate phone number
    cy.intercept('POST', '/api/validate-phone').as('validatePhone');

    // Get the phone number input field
    cy.get('[data-testid="phone-input"]').should('be.visible');

    // Type a non-numeric value
    cy.get('[data-testid="phone-input"]').type('abc123');

    // Verify the input value is still visible
    cy.get('[data-testid="phone-input"]').should('have.value', 'abc123');

    // Click the submit button
    cy.get('[data-testid="submit-btn"]').click();

    // Wait for the API validation response
    cy.wait('@validatePhone').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
    });

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid phone number');

    // Verify the input field is still visible for correction
    cy.get('[data-testid="phone-input"]').should('be.visible');
  });
});
